      {
        "factor": "Baseline near-term growth rate is insufficient for a one-day jump",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Existing growth rates imply tens of thousands per year, not thousands per day, making a one-day spike improbable."
      },
      {
        "factor": "Milestone-driven or event-driven boosts in content creation",
        "direction": "up",
        "magnitude": "weak",
